import type { FileSystem } from '@servicenow/sdk-build-core'
import { ApplicationDependencies } from '../../src/orchestrator/dependencies'
import type { Project } from '../../src/project'
import type { IConnector } from '../../src/connector'

describe('Config Update', () => {
    let mockFs: FileSystem
    let mockProject: Project
    let mockConnector: IConnector
    let appDeps: ApplicationDependencies

    beforeEach(() => {
        // Mock filesystem
        mockFs = {
            readFileSync: jest.fn(),
            writeFileSync: jest.fn(),
            existsSync: jest.fn().mockReturnValue(true),
        } as any

        // Mock project
        mockProject = {
            getFileSystem: () => mockFs,
            resolvePath: (...paths: string[]) => `/test/project/${paths.join('/')}`,
            getRootDir: () => '/test/project',
            getConfig: () => ({
                typesDir: '@types/servicenow',
                scope: 'x_test',
            }),
            getLogger: () => ({
                info: jest.fn(),
                debug: jest.fn(),
                warn: jest.fn(),
                error: jest.fn(),
            }),
            getFile: (_path: string) => {
                let content = ''
                return {
                    getContent: () => {
                        // Call the mocked readFileSync to get the configured return value
                        return (mockFs.readFileSync as jest.Mock)(_path) ?? '{}'
                    },
                    setContent: (newContent: string) => {
                        content = newContent
                    },
                    format: jest.fn().mockResolvedValue(undefined),
                    save: () => {
                        // Delegate to mockFs.writeFileSync so existing test assertions work
                        ;(mockFs.writeFileSync as jest.Mock)(_path, content)
                    },
                }
            },
        } as any

        // Mock connector
        mockConnector = {} as any

        appDeps = new ApplicationDependencies(mockProject, mockConnector)
    })

    describe('updateConfigWithNewDependencies', () => {
        it('should add new action sys_ids to config', async () => {
            const initialConfig = {
                scope: 'x_test',
                typesDir: '@types/servicenow',
                dependencies: {
                    global: {
                        'automation.actions': ['existing_action'],
                    },
                },
            }

            ;(mockFs.readFileSync as jest.Mock).mockReturnValue(JSON.stringify(initialConfig))

            // Use private method via any cast for testing
            await (appDeps as any).updateConfigWithNewDependencies('automation.actions', ['new_action'], 'global')

            // Verify writeFileSync was called
            expect(mockFs.writeFileSync).toHaveBeenCalled()

            const writeCall = (mockFs.writeFileSync as jest.Mock).mock.calls[0]
            const writtenConfig = JSON.parse(writeCall[1])

            expect(writtenConfig.dependencies.global['automation.actions']).toContain('existing_action')
            expect(writtenConfig.dependencies.global['automation.actions']).toContain('new_action')
        })

        it('should not duplicate existing sys_ids', async () => {
            const initialConfig = {
                scope: 'x_test',
                typesDir: '@types/servicenow',
                dependencies: {
                    global: {
                        'automation.actions': ['action1', 'action2'],
                    },
                },
            }

            ;(mockFs.readFileSync as jest.Mock).mockReturnValue(JSON.stringify(initialConfig))

            await (appDeps as any).updateConfigWithNewDependencies(
                'automation.actions',
                ['action1', 'action3'],
                'global'
            )

            const writeCall = (mockFs.writeFileSync as jest.Mock).mock.calls[0]
            const writtenConfig = JSON.parse(writeCall[1])

            // Should have action1, action2, action3 (no duplicate action1)
            expect(writtenConfig.dependencies.global['automation.actions']).toHaveLength(3)
            expect(
                writtenConfig.dependencies.global['automation.actions'].filter((id: string) => id === 'action1')
            ).toHaveLength(1)
        })

        it('should create new scope if it does not exist', async () => {
            const initialConfig = {
                scope: 'x_test',
                typesDir: '@types/servicenow',
                dependencies: {
                    global: {
                        'automation.actions': ['action1'],
                    },
                },
            }

            ;(mockFs.readFileSync as jest.Mock).mockReturnValue(JSON.stringify(initialConfig))

            await (appDeps as any).updateConfigWithNewDependencies('automation.actions', ['action2'], 'x_custom')

            const writeCall = (mockFs.writeFileSync as jest.Mock).mock.calls[0]
            const writtenConfig = JSON.parse(writeCall[1])

            expect(writtenConfig.dependencies.x_custom['automation.actions']).toBeDefined()
            expect(writtenConfig.dependencies.x_custom['automation.actions']).toContain('action2')
        })

        it('should preserve existing config structure', async () => {
            const initialConfig = {
                scope: 'x_test',
                typesDir: '@types/servicenow',
                someOtherField: 'preserve me',
                dependencies: {
                    global: {
                        tables: ['incident'],
                        'automation.triggers': ['trigger1'],
                    },
                },
            }

            ;(mockFs.readFileSync as jest.Mock).mockReturnValue(JSON.stringify(initialConfig))

            await (appDeps as any).updateConfigWithNewDependencies('automation.actions', ['action1'], 'global')

            const writeCall = (mockFs.writeFileSync as jest.Mock).mock.calls[0]
            const writtenConfig = JSON.parse(writeCall[1])

            // Verify other fields are preserved
            expect(writtenConfig.someOtherField).toBe('preserve me')
            expect(writtenConfig.dependencies.global.tables).toContain('incident')
            expect(writtenConfig.dependencies.global['automation.triggers']).toContain('trigger1')
        })

        it('should handle tables (using name field)', async () => {
            const initialConfig = {
                scope: 'x_test',
                typesDir: '@types/servicenow',
                dependencies: {
                    global: {
                        tables: ['incident'],
                    },
                },
            }

            ;(mockFs.readFileSync as jest.Mock).mockReturnValue(JSON.stringify(initialConfig))

            await (appDeps as any).updateConfigWithNewDependencies('tables', ['problem', 'change_request'], 'global')

            const writeCall = (mockFs.writeFileSync as jest.Mock).mock.calls[0]
            const writtenConfig = JSON.parse(writeCall[1])

            expect(writtenConfig.dependencies.global.tables).toContain('incident')
            expect(writtenConfig.dependencies.global.tables).toContain('problem')
            expect(writtenConfig.dependencies.global.tables).toContain('change_request')
        })

        it('should skip if wildcard is already set', async () => {
            const initialConfig = {
                scope: 'x_test',
                dependencies: {
                    global: {
                        'automation.actions': '*',
                    },
                },
            }

            ;(mockFs.readFileSync as jest.Mock).mockReturnValue(JSON.stringify(initialConfig))

            await (appDeps as any).updateConfigWithNewDependencies('automation.actions', ['action1'], 'global')

            // writeFileSync should NOT be called since wildcard is set
            expect(mockFs.writeFileSync).not.toHaveBeenCalled()
        })

        it('should format JSON with proper indentation', async () => {
            const initialConfig = {
                scope: 'x_test',
                dependencies: {},
            }

            ;(mockFs.readFileSync as jest.Mock).mockReturnValue(JSON.stringify(initialConfig))

            await (appDeps as any).updateConfigWithNewDependencies('automation.actions', ['action1'], 'global')

            const writeCall = (mockFs.writeFileSync as jest.Mock).mock.calls[0]
            const writtenJson = writeCall[1]

            // Should be formatted with indentation
            expect(writtenJson).toContain('\n')
            expect(writtenJson).toContain('  ') // 2-space indentation
        })
    })
})
